function mulberry32(a){ return function(){ a|=0; a=a+0x6D2B79F5|0; var t=Math.imul(a^a>>>15,1|a); t=t+Math.imul(t^t>>>7,61|t)^t; return ((t^t>>>14)>>>0)/4294967296; }; }
function sdEmpty(){ var g=[]; for(var r=0;r<9;r++){ g.push([0,0,0,0,0,0,0,0,0]); } return g; }
function sdClone(g){ return g.map(function(r){ return r.slice(); }); }
function sdShuffle(a, rnd){ for(var i=a.length-1;i>0;i--){ var j=Math.floor(rnd()*(i+1)); var t=a[i]; a[i]=a[j]; a[j]=t; } return a; }
function sdCellOk(g,r,c,v){
  for(var i=0;i<9;i++){ if(g[r][i]===v) return false; if(g[i][c]===v) return false; }
  var br=Math.floor(r/3)*3, bc=Math.floor(c/3)*3;
  for(var i=0;i<3;i++) for(var j=0;j<3;j++) if(g[br+i][bc+j]===v) return false;
  return true;
}
function sdValid(g){
  for(var r=0;r<9;r++) for(var c=0;c<9;c++){ var v=g[r][c]; if(v!==0){ g[r][c]=0; var ok=sdCellOk(g,r,c,v); g[r][c]=v; if(!ok) return false; } }
  return true;
}
function sdSolveGrid(g, rnd){
  for(var r=0;r<9;r++) for(var c=0;c<9;c++) if(g[r][c]===0){
    var nums=sdShuffle([1,2,3,4,5,6,7,8,9], rnd||Math.random);
    for(var k=0;k<9;k++){ var v=nums[k]; if(sdCellOk(g,r,c,v)){ g[r][c]=v; var res=sdSolveGrid(g,rnd); if(res) return res; g[r][c]=0; } }
    return null;
  }
  return g;
}
function sdCountSolutions(g, limit){
  for(var r=0;r<9;r++) for(var c=0;c<9;c++) if(g[r][c]===0){
    var cnt=0;
    for(var v=1;v<=9;v++){ if(sdCellOk(g,r,c,v)){ g[r][c]=v; cnt+=sdCountSolutions(g, limit); g[r][c]=0; if(cnt>=limit) return cnt; } }
    return cnt;
  }
  return 1;
}
function sdGenerate(seed, holes){
  var rnd=mulberry32(seed||1);
  var full=sdClone(sdEmpty());
  sdSolveGrid(full, rnd);
  var puzzle=sdClone(full), cells=[];
  for(var r=0;r<9;r++) for(var c=0;c<9;c++) cells.push([r,c]);
  sdShuffle(cells, rnd);
